/**
 * Put imported requirements, trace and review evidence into ISAF-generated documents (Import tab, stage 2).
 *
 * applyImport(bytes, review, options) takes a .docx generated by ISAF (it carries ISAF_DOC_IDENTITY, see
 * value_tags.js) and the result of requirements_review.js review(), and returns the document with:
 *  - HLR, LLR, HRD, REQ-Sys: a requirements table and a derived (or downward trace) table at the end of the
 *    matching sections;
 *  - Trace: the trace matrix and a gap register (trace findings with an empty disposition column);
 *  - SVCP: the imported verification cases;
 *  - VMAT-Sys (system validation matrix, ARP4754A 5.4.7.2): the validation matrix, status totals and open findings;
 *  - PR-SWRD, PR-SDD, PR-HRD checklists: evidence in the "Finding / Notes" cell of each criterion the data can
 *    speak to, and a reviewer hint for judgment criteria; Sys-SRR: evidence in "Evidence and findings" for the
 *    questions the data can speak to. The Pass / Fail / N/A (Sys-SRR: Yes / No / Open / N/A) answer is never set.
 * Everything ISAF inserts sits in Word content controls tagged "ISAF.Import:<part>#<hash>". A later import
 * replaces them in place (wherever the user moved them) and leaves everything else alone; a control whose text
 * was edited in Word is still replaced and flagged with a Word comment ("ISAF import"), because the requirements
 * tool, not the document, owns the requirements. Value refresh (value_refresh.js) keeps these controls.
 * A review aid only: the reviewer completes and signs the review. Self-contained (Customer editions have no
 * engine sources).
 */
import PizZip from '../03_Build_Engine/node_modules/pizzip/js/index.js';
import { runText, ensureCommentsPart } from './value_refresh.js';

const TAG = 'ISAF.Import:';
const AUTHOR = 'ISAF import';
const xmlEsc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const xmlUnesc = s => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
const hash = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h.toString(36); };
const ONE = { system: 'system requirement', hlr: 'software high-level requirement', hw: 'hardware requirement', llr: 'software low-level requirement', test: 'verification case', syst: 'system verification case', hlt: 'software high-level test', hwt: 'hardware verification case', llt: 'software low-level test' };
const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const list = (ids, max = 12) => ids.length ? ids.slice(0, max).join(', ') + (ids.length > max ? ` and ${ids.length - max} more` : '') : '';

/** Documents that receive imported content, by ISAF document code. */
export const TARGETS = {
  HLR: { level: 'hlr', blocks: [['records', /REQUIREMENT RECORDS/i], ['derived', /DERIVATION VERIFICATION/i]] },
  LLR: { level: 'llr', blocks: [['records', /DETAILED BEHAVIOR AND INTERFACES/i], ['derived', /VERIFICATION FEEDBACK/i]] },
  HRD: { level: 'hw', blocks: [['records', /FUNCTIONAL PERFORMANCE AND INTERFACE REQUIREMENTS/i], ['derived', /SAFETY LIFECYCLE AND DERIVED/i]] },
  'REQ-Sys': { level: 'system', blocks: [['records', /Controlled requirement record/i], ['down', /TRACE AND REVIEW/i]] },
  Trace: { level: 'hlr', blocks: [['trace', /BIDIRECTIONAL RELATIONSHIPS/i], ['gaps', /GAP ANALYSIS/i]] },
  // v5.3.37 split one 'test' level into five. `level` stays the label and parent basis; `levels`
  // is what the document collects, so verification cases imported as HLTs, LLTs, hardware or system
  // cases reach the SVCP instead of being skipped as "no imported verification cases".
  SVCP: { level: 'test', levels: ['test', 'syst', 'hlt', 'hwt', 'llt'], blocks: [['tests', /TEST CASE FORMAT/i]] },
  'VMAT-Sys': { level: 'system', blocks: [['validation', /Controlled record/i], ['vstatus', /Decision rules/i], ['vopen', /Open findings/i]] },
  'PR-SWRD': { level: 'hlr', checklist: true },
  'PR-SDD': { level: 'llr', checklist: true },
  'PR-HRD': { level: 'hw', checklist: true },
  'Sys-SRR': { level: 'system', checklist: true },
};

export function readIdentity(bytes) {
  try {
    const zip = new PizZip(bytes);
    const m = (zip.file('word/settings.xml')?.asText() || '').match(/<w:docVar w:name="ISAF_DOC_IDENTITY" w:val="([^"]*)"\s*\/>/);
    return m ? JSON.parse(xmlUnesc(m[1])) : null;
  } catch { return null; }
}

// ---------------------------------------------------------------- data for one document
function scopeFor(review, level, item) {
  const levels = [].concat(level);
  const reqs = review.requirements || [];
  const forItem = r => !item || !r.item || r.item === item;
  const byId = new Map(reqs.map(r => [r.id, r]));
  const mine = reqs.filter(r => levels.includes(r.level) && forItem(r));
  const ids = new Set(mine.map(r => r.id));
  const findings = (review.findings || []).filter(f => levels.includes(f.level) && ids.has(f.reqId));
  return { reqs, byId, mine, ids, findings, item };
}
const countChecks = (findings, checks) => checks.map(c => [c, findings.filter(f => f.check === c)]).filter(([, a]) => a.length);
const describe = (pairs) => pairs.map(([c, a]) => `${c}: ${a.length} (${list([...new Set(a.map(f => f.reqId))], 8)})`).join('; ');

// ---------------------------------------------------------------- WordprocessingML builders
const run = (text, { bold = false, size = 18, italic = false, color = '' } = {}) => {
  const rPr = `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/>${bold ? '<w:b/>' : ''}${italic ? '<w:i/>' : ''}${color ? `<w:color w:val="${color}"/>` : ''}<w:sz w:val="${size}"/><w:szCs w:val="${size}"/></w:rPr>`;
  return String(text ?? '').split('\n').map((line, i) => `${i ? `<w:r>${rPr}<w:br/></w:r>` : ''}<w:r>${rPr}<w:t xml:space="preserve">${xmlEsc(line)}</w:t></w:r>`).join('');
};
const para = (text, opts = {}) => `<w:p><w:pPr><w:spacing w:before="60" w:after="60"/></w:pPr>${run(text, opts)}</w:p>`;
const BORDER = ['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map(b => `<w:${b} w:val="single" w:sz="4" w:space="0" w:color="8C9AAB"/>`).join('');
function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const cell = (text, w, head) => `<w:tc><w:tcPr><w:tcW w:w="${Math.round(5000 * w / total)}" w:type="pct"/>${head ? '<w:shd w:val="clear" w:color="auto" w:fill="DCE3EC"/>' : ''}</w:tcPr><w:p><w:pPr><w:spacing w:before="20" w:after="20"/></w:pPr>${run(text, { bold: head, size: 16 })}</w:p></w:tc>`;
  const grid = widths.map(w => `<w:gridCol w:w="${Math.round(9600 * w / total)}"/>`).join('');
  const head = `<w:tr><w:trPr><w:tblHeader/><w:cantSplit/></w:trPr>${headers.map((h, i) => cell(h, widths[i], true)).join('')}</w:tr>`;
  const body = (rows.length ? rows : [headers.map((_, i) => i ? '' : 'None')]).map(r => `<w:tr><w:trPr><w:cantSplit/></w:trPr>${r.map((t, i) => cell(t, widths[i], false)).join('')}</w:tr>`).join('');
  return `<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:tblBorders>${BORDER}</w:tblBorders><w:tblLayout w:type="autofit"/><w:tblCellMar><w:left w:w="70" w:type="dxa"/><w:right w:w="70" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${grid}</w:tblGrid>${head}${body}</w:tbl>`;
}
let sdtCounter = 0;
const sdtId = () => 410000000 + (Date.now() % 100000) * 100 + (sdtCounter++ % 100);
function block(part, title, contentXml) {
  const text = runText(contentXml);
  return `<w:sdt><w:sdtPr><w:alias w:val="ISAF import: ${xmlEsc(title)}"/><w:tag w:val="${TAG}${part}#${hash(text)}"/><w:id w:val="${sdtId()}"/></w:sdtPr><w:sdtContent>${contentXml}</w:sdtContent></w:sdt>`;
}
function inlineControl(part, text) {
  const content = run(text, { size: 16, color: '1F3A5F' });
  return `<w:sdt><w:sdtPr><w:alias w:val="ISAF import evidence"/><w:tag w:val="${TAG}${part}#${hash(runText(content))}"/><w:id w:val="${sdtId()}"/></w:sdtPr><w:sdtContent>${content}</w:sdtContent></w:sdt>`;
}

// ---------------------------------------------------------------- section content
function intro(review, what) {
  const src = (review.meta?.sources || []).join(', ');
  return para(`${what} Imported by ISAF on ${review.meta?.generated || ''}${src ? ` from ${src}` : ''}. The requirements tool owns this content: change it there and import again, and ISAF replaces this table. Review findings are in the ISAF requirements check report.`, { italic: true, size: 16, color: '5A6B7E' });
}
const verifiedBy = r => (r.tests || []).join(', ');
function blockContent(kind, code, review, s) {
  const lvl = TARGETS[code].level;
  if (kind === 'records' && lvl === 'system') {
    const rows = s.mine.map(r => [r.id, r.text, r.parents.join(', ') || r.origin || (r.derived ? 'Derived' : ''), r.derived ? 'Yes' : 'No', [r.safety, r.dal && `DAL ${String(r.dal).replace(/^(?:F|I)?DAL\s*/i, '')}`].filter(Boolean).join('; '), r.validation || r.verification, String(r.findingCount || '')]);
    return intro(review, `Imported ${plural(s.mine.length, ONE[lvl])}.`) + table(['ID', 'Requirement', 'Source', 'Derived', 'Safety / DAL', 'Validation method', 'Findings'], rows, [10, 42, 13, 7, 12, 11, 7]);
  }
  if (kind === 'records') {
    const rows = s.mine.map(r => [r.id, r.text, r.parents.join(', ') || (r.derived ? 'Derived' : ''), r.derived ? 'Yes' : 'No', r.verification, String(r.findingCount || '')]);
    return intro(review, `Imported ${plural(s.mine.length, ONE[lvl])}.`) + table(['ID', 'Requirement', lvl === 'system' ? 'Parent' : 'Traces to', 'Derived', 'Verification method', 'Findings'], rows, [10, 46, 14, 7, 13, 7]);
  }
  if (kind === 'derived') {
    const d = s.mine.filter(r => r.derived);
    return intro(review, `Derived ${ONE[lvl]}s (${d.length}). Provide each to the system and safety assessment processes and record their response.`) + table(['ID', 'Requirement', 'Rationale', 'Safety assessment feedback'], d.map(r => [r.id, r.text, r.rationale || '(no rationale recorded)', '']), [10, 44, 28, 18]);
  }
  if (kind === 'down') {
    const rows = s.mine.map(r => [r.id, (r.children || []).join(', '), verifiedBy(r), (s.findings.filter(f => f.reqId === r.id).map(f => f.check)).join('; ')]);
    return intro(review, `Downward trace of ${plural(s.mine.length, ONE[lvl])}.`) + table(['System requirement', 'Developed by (software / hardware requirements)', 'Verified by', 'Review findings'], rows, [16, 40, 20, 24]);
  }
  if (kind === 'trace') {
    const rows = [];
    for (const level of ['hlr', 'llr']) for (const r of s.reqs.filter(x => x.level === level && (!s.item || !x.item || x.item === s.item))) rows.push([r.id, r.levelLabel, r.parents.join(', ') || (r.derived ? 'Derived' : ''), (r.children || []).join(', '), verifiedBy(r)]);
    return intro(review, `Trace of ${plural(rows.length, 'requirement')} (software high-level and low-level) to parents, lower-level requirements and verification cases.`) + table(['Requirement', 'Level', 'Traces to', 'Developed by', 'Verified by'], rows, [14, 20, 20, 24, 22]);
  }
  if (kind === 'gaps') {
    const TRACE = new Set(['Not traced', 'Broken trace link', 'Trace to unexpected level', 'Not developed further', 'No test', 'Test not traced', 'Derived without rationale']);
    const ids = new Set(s.reqs.filter(x => ['hlr', 'llr', 'test'].includes(x.level) && (!s.item || !x.item || x.item === s.item)).map(x => x.id));
    const gaps = (review.findings || []).filter(f => TRACE.has(f.check) && ids.has(f.reqId));
    return intro(review, `Trace gaps found by the import (${gaps.length}). Record a disposition for each.`) + table(['Requirement', 'Gap', 'Detail', 'Disposition'], gaps.map(f => [f.reqId, f.check, f.message, '']), [14, 18, 44, 24]);
  }
  if (kind === 'validation') {
    const rows = s.mine.map(r => [r.id, r.parents.join(', ') || r.origin || (r.derived ? `Derived: ${r.rationale || 'no rationale'}` : ''), '', r.dal || '', r.validation || '', '', r.validationStatus || 'Open']);
    return intro(review, `Validation matrix of ${plural(s.mine.length, ONE.system)}. Associated function and validation evidence references are for the engineer to complete.`) + table(['Requirement', 'Source', 'Associated function', 'DAL', 'Validation method', 'Validation evidence', 'Conclusion'], rows, [12, 18, 16, 6, 16, 18, 14]);
  }
  if (kind === 'vstatus') {
    const by = new Map(); for (const r of s.mine) { const k = r.validationStatus || 'Open (no conclusion recorded)'; by.set(k, (by.get(k) || 0) + 1); }
    const assumed = s.mine.filter(r => r.assumption).map(r => r.id), noMethod = s.mine.filter(r => !r.validation).map(r => r.id);
    const rows = [...by.entries()].map(([k, v]) => [k, String(v)]);
    rows.push(['Without validation method', `${noMethod.length}${noMethod.length ? ` (${list(noMethod)})` : ''}`], ['Based on an assumption', `${assumed.length}${assumed.length ? ` (${list(assumed)})` : ''}`], ['Derived', String(s.mine.filter(r => r.derived).length)]);
    return intro(review, `Validation status of ${plural(s.mine.length, ONE.system)}.`) + table(['Status', 'Requirements'], rows, [40, 60]);
  }
  if (kind === 'vopen') {
    const OPEN = new Set(['No validation method', 'Not yet validated', 'Based on an assumption', 'Source not identified', 'Safety requirement without DAL', 'Safety requirement not allocated', 'Invalid DAL', 'Derived without rationale', 'Ambiguous or open term', 'No tolerance', 'No validation data']);
    const open = (review.findings || []).filter(f => f.level === 'system' && OPEN.has(f.check));
    return intro(review, `Open validation findings from the import (${open.length}). Record the owner and the planned resolution for each.`) + table(['Requirement', 'Finding', 'Detail', 'Owner and resolution'], open.map(f => [f.reqId, f.check, f.message, '']), [14, 20, 42, 24]);
  }
  if (kind === 'tests') {
    return intro(review, `Imported ${plural(s.mine.length, ONE.test)}.`) + table(['Verification case', 'Description', 'Verifies'], s.mine.map(r => [r.id, r.text, r.parents.join(', ')]), [16, 60, 24]);
  }
  return '';
}

// ---------------------------------------------------------------- checklist evidence
function evidence(code, ref, criterion, review, s) {
  const lvl = TARGETS[code].level, one = ONE[lvl], n = s.mine.length;
  if (!n) return null;
  const parentLevel = { hlr: 'system', llr: 'hlr', hw: 'system', system: 'system' }[lvl];
  const head = `ISAF import (${review.meta?.generated || ''}): `;
  const traced = s.mine.filter(r => r.parents.some(p => s.byId.has(p)));
  const untraced = s.findings.filter(f => f.check === 'Not traced' || f.check === 'Broken trace link');
  const up = () => `${traced.length} of ${plural(n, one)} trace to a ${ONE[parentLevel]}; ${s.mine.filter(r => r.derived).length} derived.${untraced.length ? ` Not traced or broken links: ${list([...new Set(untraced.map(f => f.reqId))])}.` : ''}`;
  const down = () => {
    if (lvl === 'system') { const open = s.mine.filter(r => !(r.children || []).length); return `${n - open.length} of ${plural(n, one)} are developed by software or hardware requirements.${open.length ? ` Not developed here: ${list(open.map(r => r.id))}.` : ''}`; }
    const parents = s.reqs.filter(r => r.level === parentLevel && (lvl === 'llr' ? (!s.item || !r.item || r.item === s.item) : true));
    if (!parents.length) return `No ${ONE[parentLevel]}s were imported, so downward coverage cannot be shown.`;
    const open = parents.filter(p => !s.mine.some(c => c.parents.includes(p.id)));
    return `${parents.length - open.length} of ${plural(parents.length, ONE[parentLevel])} are developed by at least one ${one}.${open.length ? ` Not developed here: ${list(open.map(p => p.id))} (confirm whether each is allocated to this item).` : ''}`;
  };
  const derived = () => { const d = s.mine.filter(r => r.derived), no = d.filter(r => !r.rationale); return `${plural(d.length, `derived ${one}`)}${d.length ? `: ${list(d.map(r => r.id))}` : ''}.${no.length ? ` Without rationale: ${list(no.map(r => r.id))}.` : d.length ? ' All have a rationale.' : ''}${d.length ? ' Confirm each was provided to the system safety assessment.' : ''}`; };
  const checks = (names, ok) => { const pairs = countChecks(s.findings, names); return pairs.length ? `Findings: ${describe(pairs)}.` : ok; };
  const verif = () => checks(['No "shall"', 'Compound requirement', 'No verification method', 'Value without unit', 'Negative requirement', 'Empty text'], `All ${plural(n, one)} have one "shall", a verification method and units for numeric values.`);
  const clarity = () => checks(['Ambiguous or open term', 'Duplicate text', 'Duplicate ID'], 'No ambiguous or open terms, duplicate texts or duplicate IDs found.') + ' Accuracy and consistency remain reviewer judgment.';
  const conform = () => checks(['Missing ID', 'Duplicate ID', 'No "shall"', 'Compound requirement', 'Ambiguous or open term', 'Value without unit', 'Long requirement', 'No verification method'], 'Identification, wording, units and verification method rules checked: no findings.') + ' Other rules of the standard: reviewer.';
  const validated = () => { const d = s.mine.filter(r => r.derived); if (!d.length) return ''; const open = d.filter(r => !r.validation && !/^(valid|validated|accepted|approved|complete|completed|closed|yes|y|ok|passed?)$/i.test(r.validationStatus || '')); return open.length ? `Derived without a validation method or conclusion: ${list(open.map(r => r.id))}.` : 'Each derived requirement has a validation method or conclusion.'; };
  const errors = () => `The ISAF requirements check report lists ${plural((review.findings || []).filter(f => s.ids.has(f.reqId)).length, 'finding')} for these requirements, for resolution by the owning process.`;
  const judge = what => `Reviewer judgment (${what}). ISAF has no data for this criterion.`;
  const c = String(criterion), r = String(ref);
  const has = re => re.test(r);
  if (code === 'PR-SWRD' || code === 'PR-SDD') {
    const a = code === 'PR-SWRD' ? '1' : '2';
    if (has(new RegExp(`6\\.3\\.${a}f`))) return head + (/upward|traceable to/i.test(c) ? up() : down());
    if (has(new RegExp(`6\\.3\\.${a}a`))) return head + (/each (system requirement|HLR)|corresponding|covered|unimplemented/i.test(c) ? down() : clarity());
    if (has(new RegExp(`6\\.3\\.${a}b`))) return head + clarity();
    if (has(new RegExp(`6\\.3\\.${a}d`))) return head + verif();
    if (has(new RegExp(`6\\.3\\.${a}e`))) return /prohibited|recursion/i.test(c) ? null : head + conform();
    if (has(new RegExp(`6\\.3\\.${a}c`))) return head + judge('target computer compatibility');
    if (has(new RegExp(`6\\.3\\.${a}g`))) return head + judge('algorithm accuracy');
    if (has(new RegExp(`5\\.${a}\\.1b`))) return head + derived();
    if (has(new RegExp(`5\\.${a}\\.1a`))) return code === 'PR-SDD' && !/low-level|LLR/i.test(c) ? null : head + `${plural(n, one)} imported. ` + up() + (/safety/i.test(c) ? ' Safety-related identification: reviewer.' : '');
    return null;
  }
  if (code === 'Sys-SRR') {
    const q = (c.match(/^\s*Q(\d+)/) || [])[1];
    const safety = s.mine.filter(x => x.safety), assumed = s.mine.filter(x => x.assumption), valid = s.mine.filter(x => /^(valid|validated|accepted|approved|complete|completed|closed|yes|y|ok|passed?)$/i.test(x.validationStatus || ''));
    const open = s.findings.filter(f => f.check === 'Ambiguous or open term' && /TB[DCR]/i.test(f.message));
    if (q === '2') return head + `${plural(n, one)} imported from ${(review.meta?.sources || []).join(', ')}. ${checks(['Source not identified', 'Broken trace link'], 'Each requirement has a source, a parent or is derived.')} ${s.mine.filter(x => x.derived).length} derived.`;
    if (q === '3') { const k = s.findings.filter(f => f.severity !== 'Info'); return head + `${plural(k.length, 'error or warning')} from the automatic checks (wording, tolerances, verifiability, source, validation). Validation conclusion valid for ${valid.length} of ${n}. Set completeness: reviewer.`; }
    if (q === '4') return head + `${plural(safety.length, 'safety-related requirement')}${safety.length ? ` (${list(safety.map(x => x.id))})` : ''}; ${plural(assumed.length, 'requirement')} based on an assumption${assumed.length ? ` (${list(assumed.map(x => x.id))})` : ''}. ${checks(['Safety requirement without DAL', 'Invalid DAL'], safety.length ? 'Safety requirements have a valid DAL.' : '')} FHA and classification rationale: reviewer.`.replace(/\s+$/, '');
    if (q === '5') return head + down().replace('Not developed here', 'Not allocated');
    if (q === '7') return head + `Open items: ${plural(open.length, 'requirement')} with TBD/TBC/TBR${open.length ? ` (${list([...new Set(open.map(f => f.reqId))])})` : ''}; ${plural(assumed.length, 'assumption')} to resolve; ${plural(n - valid.length, 'requirement')} not yet validated.`;
    return null;
  }
  if (code === 'PR-HRD') {
    if (/5\.1\.2\s*\(8\)/.test(r)) return head + up();
    if (/5\.1\.1\s*\(2\)|5\.1\.2\s*\(5\)/.test(r)) return head + derived() + ' ' + validated();
    if (/5\.1\.1\s*\(3\)|5\.1\.2\s*\(7\)/.test(r)) return head + errors();
    if (/5\.1\.2\s*\(3/.test(r)) return head + derived() + ' ' + checks(['Value without unit', 'No tolerance', 'Possible design detail'], 'Measured values have units and tolerances; no design wording found.') + ' ' + validated();
    if (/5\.1\.2\s*\(1|5\.1\.1\s*\(1\)/.test(r)) return head + `${plural(n, one)} imported (${s.mine.filter(x => !x.derived).length} allocated, ${s.mine.filter(x => x.derived).length} derived). ` + verif();
    return null;
  }
  return null;
}

// ---------------------------------------------------------------- document edits
const BODY_CHILD = /<w:p\b[^>]*>[\s\S]*?<\/w:p>|<w:p\b[^>]*\/>/g;
function headingAt(docXml, re) {
  // Top-level heading paragraphs: style Heading1-3 (or "N.N TITLE" text in a heading style).
  const out = [];
  for (const m of docXml.matchAll(BODY_CHILD)) {
    const style = m[0].match(/<w:pStyle w:val="(?:Heading|heading)\s?(\d)"/);
    if (!style) continue;
    out.push({ index: m.index, end: m.index + m[0].length, level: Number(style[1]), text: runText(m[0]) });
  }
  const i = out.findIndex(h => re.test(h.text));
  if (i < 0) return null;
  const next = out.slice(i + 1).find(h => h.level <= out[i].level);
  let at = next ? next.index : docXml.lastIndexOf('<w:sectPr');
  if (at < 0) at = docXml.lastIndexOf('</w:body>');
  return { at };
}
const BLOCK_RE = part => new RegExp(`<w:sdt>(?:(?!<w:sdt>)[\\s\\S])*?<w:tag w:val="${TAG.replace('.', '\\.')}${part}#([a-z0-9]+)"[\\s\\S]*?<\\/w:sdtContent><\\/w:sdt>`);

/** Apply an import review to one document. Returns { bytes, changed, report:{code,item,blocks[],rows,edited[],skipped} }. */
export function applyImport(bytes, review, { date = new Date().toISOString().replace(/\.\d+Z$/, 'Z') } = {}) {
  const zip = new PizZip(bytes);
  const identity = readIdentity(bytes);
  const code = identity?.doc, target = TARGETS[code];
  const report = { code: code || '', item: identity?.item || '', pn: identity?.pn || '', blocks: [], rows: 0, edited: [], skipped: '' };
  if (!identity) { report.skipped = 'not an ISAF document (generated by ISAF 5.3.26 or later)'; return { bytes, changed: false, report }; }
  if (!target) { report.skipped = 'this document type does not take imported requirements'; return { bytes, changed: false, report }; }
  const s = scopeFor(review, target.levels || target.level, identity.item);
  if (!s.mine.length) { report.skipped = `no imported ${ONE[target.level]}s${identity.item ? ` for ${identity.item}` : ''}`; return { bytes, changed: false, report }; }
  let doc = zip.file('word/document.xml').asText();
  const flagged = [];
  const place = (part, xml, sectionRe) => {
    const re = BLOCK_RE(part), old = doc.match(re);
    if (old) {
      const content = /<w:sdtContent>([\s\S]*)<\/w:sdtContent>/.exec(old[0])[1];
      if (hash(runText(content)) !== old[1]) { report.edited.push(part); flagged.push(part); xml = xml.replace(/(<w:sdtContent><w:p>(?:<w:pPr>(?:(?!<\/w:pPr>)[\s\S])*<\/w:pPr>)?)/, `$1\u0000ISAFC${flagged.length - 1}\u0000`).replace(/(<w:sdtContent><w:p>[\s\S]*?)(<\/w:p>)/, `$1\u0000ISAFE${flagged.length - 1}\u0000$2`); }
      doc = doc.replace(old[0], () => xml); return true;
    }
    const h = sectionRe && headingAt(doc, sectionRe);
    if (!h) return false;
    doc = doc.slice(0, h.at) + xml + doc.slice(h.at); return true;
  };
  if (target.blocks) {
    for (const [kind, re] of target.blocks) {
      const content = blockContent(kind, code, review, s);
      if (content && place(kind, block(kind, kind, content), re)) report.blocks.push(kind);
    }
  }
  if (target.checklist) {
    doc = doc.replace(/<w:tbl>[\s\S]*?<\/w:tbl>/g, tbl => {
      const rows = [...tbl.matchAll(/<w:tr\b[^>]*>[\s\S]*?<\/w:tr>/g)];
      if (!rows.length) return tbl;
      const head = [...rows[0][0].matchAll(/<w:tc>[\s\S]*?<\/w:tc>/g)].map(c => runText(c[0]).trim());
      const at = re => head.findIndex(h => re.test(h));
      const evi = at(/^Finding \/ Notes|^Evidence and findings/i), crit = at(/Check Item|^Criterion|^Review question/i), refCol = at(/^Ref/i), numCol = at(/^#$/);
      if (evi < 0 || crit < 0) return tbl;
      let index = 0;
      return tbl.replace(/<w:tr\b[^>]*>[\s\S]*?<\/w:tr>/g, tr => {
        index++;
        const cells = [...tr.matchAll(/<w:tc>[\s\S]*?<\/w:tc>/g)];
        if (index === 1 || cells.length <= evi) return tr;
        const txt = i => (i >= 0 && cells[i] ? runText(cells[i][0]).trim() : '');
        const criterion = txt(crit), num = txt(numCol) || (criterion.match(/^\s*(Q\d+)/) || [])[1] || String(index);
        const text = evidence(code, txt(refCol), criterion, review, s);
        if (!text) return tr;
        const part = `chk.${num}`;
        const cell = cells[evi][0];
        const existing = cell.match(BLOCK_RE(part.replace(/\./g, '\\.')));
        let neu;
        if (existing) neu = cell.replace(existing[0], () => inlineControl(part, text));
        else if (!runText(cell).trim()) neu = cell.replace(/(<w:p\b[^>]*>(?:<w:pPr>(?:(?!<\/w:pPr>)[\s\S])*<\/w:pPr>)?)((?:(?!<\/w:p>)[\s\S])*)(<\/w:p>)/, (m, a, b, c) => `${a}${inlineControl(part, text)}${c}`);
        else neu = cell.replace(/<\/w:tc>$/, `<w:p>${inlineControl(part, text)}</w:p></w:tc>`);
        report.rows++;
        return tr.replace(cell, () => neu);
      });
    });
    if (report.rows) report.blocks.push('checklist');
  }
  if (!report.blocks.length) { report.skipped = 'the expected sections were not found (the document structure was changed)'; return { bytes, changed: false, report }; }
  if (flagged.length) {
    ensureCommentsPart(zip);
    let comments = zip.file('word/comments.xml').asText();
    const used = [...comments.matchAll(/w:id="(\d+)"/g), ...doc.matchAll(/<w:comment(?:RangeStart|RangeEnd|Reference) w:id="(\d+)"/g)].map(m => Number(m[1]));
    let next = (used.length ? Math.max(...used) : -1) + 1;
    const ids = flagged.map(() => next++);
    doc = doc.replace(/\u0000ISAF([CE])(\d+)\u0000/g, (_, k, i) => k === 'C' ? `<w:commentRangeStart w:id="${ids[i]}"/>` : `<w:commentRangeEnd w:id="${ids[i]}"/><w:r><w:rPr><w:rStyle w:val="CommentReference"/></w:rPr><w:commentReference w:id="${ids[i]}"/></w:r>`);
    comments = comments.replace(/<\/w:comments>\s*$/, flagged.map((_, i) => `<w:comment w:id="${ids[i]}" w:author="${AUTHOR}" w:date="${date}" w:initials="ISAF"><w:p><w:r><w:t xml:space="preserve">ISAF import: this table had been edited in Word. It was replaced by the import of ${xmlEsc(review.meta?.generated || date)}; the requirements tool owns this content. Check the changes, then delete this comment.</w:t></w:r></w:p></w:comment>`).join('') + '</w:comments>');
    zip.file('word/comments.xml', comments);
  }
  zip.file('word/document.xml', doc);
  return { bytes: zip.generate({ type: 'nodebuffer', compression: 'DEFLATE' }), changed: true, report };
}

export function importReportText(results, review) {
  const lines = [`ISAF requirements import: documents updated`, `Import: ${review.meta?.generated || ''}${review.meta?.program ? `, program ${review.meta.program}` : ''}`, `Sources: ${(review.meta?.sources || []).join(', ')}`, '',
    'ISAF inserted the imported requirements, trace and checklist evidence into the documents below. Inserted content is in Word content controls marked "ISAF import" and is replaced on the next import. Checklist Pass / Fail / N/A answers are left to the reviewer.', ''];
  const done = results.filter(r => r.changed), skipped = results.filter(r => !r.changed);
  lines.push(`Updated (${done.length}):`);
  for (const r of done) lines.push(`  ${r.name}: ${r.report.code}${r.report.item ? ` (${r.report.item})` : ''}: ${r.report.blocks.map(b => b === 'checklist' ? `${r.report.rows} checklist rows` : b).join(', ')}${r.report.edited.length ? `; replaced tables that had been edited in Word: ${r.report.edited.join(', ')} (Word comment added)` : ''}`);
  if (skipped.length) { lines.push('', `Not changed (${skipped.length}):`); for (const r of skipped) lines.push(`  ${r.name}: ${r.report.skipped || r.error || ''}`); }
  return lines.join('\n') + '\n';
}
